import React, { useState, useEffect, createContext, useContext, useCallback, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter, Routes, Route, Link, Navigate, useNavigate, useLocation } from 'react-router-dom';
import { Sprout, ArrowUpRight, ArrowRight, ArrowLeft, Menu, X, Droplets, Thermometer, Leaf, Activity, Download, Radio, Check, CheckCircle2, Clock3, Users, FileText, Settings2, LogOut, Mail, MessageCircle, ChevronDown, ShieldCheck, Search, RefreshCw, CircleHelp, LayoutDashboard, Plus, HeartHandshake, Waves, FlaskConical, Sun, MapPin } from 'lucide-react';
